FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 083: face blends with two solutions and a help point, hold lines and a cliff edge inside a side. Generated by tools/fixtures/gen-batch-083.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

// Each face of a body: its area and its surface's type.
function faceProbe(context is Context, body is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qOwnedByBody(body, EntityType.FACE)))
    {
        var entry = { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6) };
        try
        {
            entry["type"] = evSurfaceDefinition(context, { "face" : face, "returnBSplinesAsOther" : true }).surfaceType;
        }
        catch (error)
        {
            entry["type"] = "failed";
        }
        out = append(out, entry);
    }
    return out;
}

// face-blend: a floor sheet and a Π-shaped sheet's two walls standing on it 20 mm apart, blended 3 mm, a help point at (15, 18, 1) picking one
export function c001(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "r1", { "firstCorner" : vector(0, -5) * millimeter, "secondCorner" : vector(30, 25) * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skLineSegment(s2, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(0, 15) * millimeter });
    skLineSegment(s2, "l2", { "start" : vector(0, 15) * millimeter, "end" : vector(20, 15) * millimeter });
    skLineSegment(s2, "l3", { "start" : vector(20, 15) * millimeter, "end" : vector(20, 0) * millimeter });
    skSolve(s2);
    extrude(context, id + "walls", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "s2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter, "oppositeDirection" : false });
    opPoint(context, id + "help", { "point" : vector(15, 18, 1) * millimeter });
    faceBlend(context, id + "blend1", { "side1" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide1" : false, "side2" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "walls", EntityType.BODY), BodyType.SHEET), EntityType.FACE), vector(15, 0, 7) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "walls", EntityType.BODY), BodyType.SHEET), EntityType.FACE), vector(15, 20, 7) * millimeter)]), "flipSide2" : false, "radius" : 3 * millimeter, "propagation" : false, "crossSection" : FaceBlendCrossSection.ROLLING_BALL, "blendControlType" : BlendControlType.RADIUS, "asymmetric" : false, "crossSectionShape" : FaceBlendCrossSectionShape.CIRCULAR, "tangentHoldLines" : false, "conicHoldLines" : false, "hasCliffEdges" : false, "hasCaps" : false, "hasLimits" : false, "hasHelpPoint" : true, "trim" : FaceBlendTrimType.WALLS, "detach" : false, "showSelection" : false, "showIsocurves" : false, "helpPoint" : qCreatedBy(id + "help", EntityType.VERTEX) });
    return { "floor" : faceProbe(context, qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.SHEET)) };
}

